INSERT INTO public."Product" (id, slug, name, description, price, active, status, "productType", category, featured, "isNew", "displayOrder", "packQuantity", dimensions, material, finish, note, rarity, "seriesId", metadata)
VALUES
  ('stk-marvel-240', 'chibi-loki-your-savior-is-here', 'Chibi Loki ''Your Savior Is Here!''', 'Smiling chibi Loki with curved golden horns and flowing green cape proclaiming ''Your Savior Is Here!''.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 295, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'common', 'S01', NULL),
  ('stk-marvel-241', 'iron-man-mark-46-full-power-repulsor-blast', 'Iron Man Mark 46 Full-Power Repulsor Blast', 'Iron Man soaring forward in crimson and gold armor firing a radiant white-hot repulsor beam directly at the viewer.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 296, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'common', 'S01', NULL),
  ('stk-marvel-242', 'the-amazing-spider-man-nyc-skyline-vintage-poster', 'The Amazing Spider-Man NYC Skyline Vintage Poster', 'Retro newsprint poster of Spider-Man overlooking the Empire State Building with the immortal quote: ''With Great Power Comes Great Responsibility''.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 297, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'common', 'S01', NULL),
  ('stk-marvel-243', 'captain-america-and-winter-soldier-split-shield', 'Captain America & Winter Soldier Split Shield', 'Circular split emblem pairing Steve Rogers'' red-and-blue star shield with Bucky Barnes'' titanium arm and Soviet red star.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 298, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'common', 'S01', NULL),
  ('stk-marvel-244', 'chibi-doctor-doom-hovering-magic', 'Chibi Doctor Doom Hovering Magic', 'Cute floating chibi Victor Von Doom in green tunic and cape preparing to cast Latverian sorcery.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 299, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'common', 'S01', NULL),
  ('stk-marvel-245', 'tony-stark-legends-never-die-photo-collage', 'Tony Stark ''Legends Never Die'' Photo Collage', 'Comprehensive memorial collage honoring Robert Downey Jr.''s Tony Stark with arc reactor, Iron Man suits, and famous MCU quotes.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 300, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'rare', 'S01', NULL),
  ('stk-marvel-246', 'doctor-doom-and-iron-man-armored-gauntlet-fist-bump', 'Doctor Doom & Iron Man Armored Gauntlet Fist Bump', 'Retro comic panel of Doctor Doom''s steel gauntlet and Iron Man''s red-and-gold armor fist-bumping in mutual respect.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 301, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'common', 'S01', NULL),
  ('stk-marvel-247', 'chibi-thor-stormbreaker-lightning-surge', 'Chibi Thor Stormbreaker Lightning Surge', 'Cute chibi Thor kneeling with glowing white eyes while raising Stormbreaker into a storm of crackling blue thunderbolts.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 302, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'common', 'S01', NULL),
  ('stk-marvel-248', 'tony-stark-i-am-iron-man-monolith-poster', 'Tony Stark ''I Am Iron Man'' Monolith Poster', 'Robert Downey Jr. in his tailored pinstripe suit posing with outstretched arms against a stark crimson rectangle and Avengers logo.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 303, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'common', 'S01', NULL),
  ('stk-marvel-249', 'tony-starks-original-arc-reactor-proof-that-tony-stark-has-a-heart', 'Tony Stark''s Original Arc Reactor ''Proof That Tony Stark Has A Heart''', 'Pepper Potts'' sentimental display case of Tony''s first Mk 1 miniature arc reactor inscribed ''Proof That Tony Stark Has A Heart''.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 304, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'common', 'S01', NULL),
  ('stk-marvel-250', 'marvel-comic-strip-classic-box-logo', 'Marvel Comic Strip Classic Box Logo', 'Wide red rectangular banner with the iconic MARVEL logo filled with black-and-white classic comic panels.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 305, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'common', 'S01', NULL),
  ('stk-marvel-251', 'batman-gotham-night-minimalist-yellow-poster', 'Batman Gotham Night Minimalist Yellow Poster', 'Sharp black Bat insignia centered boldly on a vibrant Gotham yellow poster field.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 306, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'common', 'S01', NULL),
  ('stk-marvel-252', 'avengers-infinity-war-a-hero-collage', 'Avengers Infinity War ''A'' Hero Collage', 'The iconic Avengers ''A'' logo filled with dynamic action portraits of Earth''s Mightiest Heroes and Guardians of the Galaxy.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 307, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'common', 'S01', NULL),
  ('stk-marvel-253', 'thanos-infinity-gauntlet-snarl', 'Thanos Infinity Gauntlet Snarl', 'The Mad Titan Thanos grinning menacingly while wielding the complete Infinity Gauntlet with all 6 glowing Infinity Stones.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 308, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'common', 'S01', NULL),
  ('stk-marvel-254', 'chibi-black-panther-vibranium-habit', 'Chibi Black Panther Vibranium Habit', 'Cute mini King T''Challa in his detailed silver-accented Black Panther suit with white reflective eyes.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 309, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'common', 'S01', NULL),
  ('stk-marvel-255', 'deadpool-do-i-look-like-i-care-sarcastic-poster', 'Deadpool ''Do I Look Like I Care?'' Sarcastic Poster', 'Wade Wilson shrugging with hands palms up under distressed typography: ''Do I Look Like I Care?''.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 310, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'rare', 'S01', NULL),
  ('stk-marvel-256', 'chibi-infamous-iron-man-victor-von-doom', 'Chibi Infamous Iron Man Victor Von Doom', 'Cute chibi Victor Von Doom combining his green hood with a gold-and-red Iron Man armor plate and chest arc reactor.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 311, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'common', 'S01', NULL),
  ('stk-marvel-257', 'deadpool-bench-nap-zzz-poster', 'Deadpool Bench Nap ''Zzz'' Poster', 'Humorous minimalist poster of Deadpool sprawled out fast asleep on a park bench under a bright yellow sunny sky.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 312, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'common', 'S01', NULL),
  ('stk-marvel-258', 'avengers-doomsday-victor-von-doom-title-poster', 'Avengers: Doomsday Victor Von Doom Title Poster', 'Ominous Doctor Doom with folded metal gauntlets cloaked in green above the metallic ''AVENGERS: DOOMSDAY'' logo.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 313, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'common', 'S01', NULL),
  ('stk-marvel-259', 'marvel-red-cosmic-nebula-deep-space-poster', 'Marvel Red Cosmic Nebula Deep Space Poster', 'The classic white-on-red Marvel logo floating in the radiant heart of a glowing stellar cosmic nebula.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 314, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'common', 'S01', NULL),
  ('stk-marvel-260', 'chibi-doctor-strange-mystic-mandala-circles', 'Chibi Doctor Strange Mystic Mandala Circles', 'Cute chibi Stephen Strange hovering with the Eye of Agamotto and multiple glowing orange Tao mandalas.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 315, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'common', 'S01', NULL),
  ('stk-marvel-261', 'the-incredible-hulk-leap-fist-comic-art', 'The Incredible Hulk Leap Fist Comic Art', 'Vintage comic book art of the Incredible Hulk launching forward through the air with clenched fist ready to smash.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 316, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'common', 'S01', NULL),
  ('stk-marvel-262', 'the-flash-scarlet-speedster-comic-bust', 'The Flash Scarlet Speedster Comic Bust', 'Classic DC superhero Barry Allen in his iconic crimson cowl with golden lightning bolt chest crest and ear wings.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 317, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'common', 'S01', NULL),
  ('stk-marvel-263', 'doctor-doom-and-iron-man-crest-arc-reactor-split', 'Doctor Doom & Iron Man Crest Arc Reactor Split', 'Circular split badge showing the green Latverian Doom monogram on the left and Tony Stark''s glowing arc reactor on the right.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 318, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'common', 'S01', NULL),
  ('stk-marvel-264', 'doctor-strange-master-of-the-mystic-arts-galaxy-poster', 'Doctor Strange Master of the Mystic Arts Galaxy Poster', 'Stephen Strange striding confidently through sacred geometric spells and celestial astrological wheels.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 319, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'common', 'S01', NULL),
  ('stk-marvel-265', 'doctor-strange-shield-of-the-seraphim-runic-magic', 'Doctor Strange Shield of the Seraphim Runic Magic', 'Benedict Cumberbatch as Doctor Strange projecting a blazing fiery runic mandala shield from his outstretched hand.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 320, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'rare', 'S01', NULL),
  ('stk-marvel-266', 'doctor-strange-blood-red-moon-skyline-silhouette', 'Doctor Strange Blood Red Moon Skyline Silhouette', 'Dramatic dark silhouette of Doctor Strange levitating high over New York City within a blood-red mystic moon ring.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 321, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'common', 'S01', NULL),
  ('stk-marvel-267', 'sanctum-sanctorum-window-of-the-worlds-blueprint', 'Sanctum Sanctorum Window of the Worlds Blueprint', 'Crisp architectural line art of Doctor Strange''s iconic circular Sanctum Sanctorum skylight (Seal of the Vishanti).', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 322, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'common', 'S01', NULL),
  ('stk-marvel-268', 'doctor-strange-sorcerer-supreme-walking-incantation', 'Doctor Strange Sorcerer Supreme Walking Incantation', 'Full-length illustration of Doctor Strange walking forward in flowing Cloak of Levitation with a blazing fiery spell sphere.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 323, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'common', 'S01', NULL),
  ('stk-marvel-269', 'spider-man-gwen-stacy-the-plunge-silhouette', 'Spider-Man & Gwen Stacy ''The Plunge'' Silhouette', 'Haunting silhouette poster of Spider-Man diving on a web strand to save Gwen Stacy falling into the abyss.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 324, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'common', 'S01', NULL),
  ('stk-marvel-270', 'mjolnir-armored-forearm-lightning-grasp', 'Mjolnir Armored Forearm Lightning Grasp', 'Powerful graphic of Thor''s golden armored gauntlet clutching Mjolnir as bright blue lightning arcs across the sky.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 325, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'common', 'S01', NULL),
  ('stk-marvel-271', 'captain-america-heroic-charge-starburst-badge', 'Captain America Heroic Charge Starburst Badge', 'Classic comic Cap sprinting into action with his vibranium shield against an explosive red-and-blue starburst.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 326, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'common', 'S01', NULL),
  ('stk-marvel-272', 'spider-man-web-slinger-dynamic-comic-collage', 'Spider-Man Web Slinger Dynamic Comic Collage', 'Action-packed perspective of Spider-Man reaching forward shooting webs over a dense red-and-black collage of comic book panels.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 327, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'common', 'S01', NULL),
  ('stk-marvel-273', 'chibi-avengers-peeking-ledge-cuties', 'Chibi Avengers Peeking Ledge Cuties', 'Super cute horizontal decal of mini Spider-Man, Iron Man, Captain America, Hulk, and Thor peeking over a ledge.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 328, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'common', 'S01', NULL),
  ('stk-marvel-274', 'chibi-hawkeye-peeking-archer', 'Chibi Hawkeye Peeking Archer', 'Adorable chibi Clint Barton in purple tactical gear with bow and arrows peeking shyly from the edge.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 329, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'common', 'S01', NULL),
  ('stk-marvel-275', 'classic-spider-man-nyc-skyscraper-leap-poster', 'Classic Spider-Man NYC Skyscraper Leap Poster', 'Vintage pulp-style comic poster of Spider-Man leaping between New York City skyscrapers above the Empire State Building.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 330, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'rare', 'S01', NULL),
  ('stk-marvel-276', 'thor-god-of-thunder-purple-wave-poster', 'Thor ''God of Thunder'' Purple Wave Poster', 'Chris Hemsworth as Thor surrounded by crackling lightning against purple wavy typography reading ''GOD OF THUNDER THOR''.', 20, TRUE, 'PUBLISHED', 'single', 'stickers', FALSE, TRUE, 331, NULL, '5-7 cm', 'Vinyl', 'Matte', NULL, 'common', 'S01', NULL),
